const brandLogo="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgPiFlnDAIqYkcjYOq7GqeHClxkSC9yrmNm0UypICcP-HfjzV2zxtWUrPqqYrYgU-acx7q4lHjYuN4qIqrxozuphAsy0Ezq5dhZy0u5ZG5rKH2xC7OKyI-n4HwlhLQ2WZKj6ydM1UOLEKw_LDh04yQEqYU_QuA1OqAB90XfhmZ9fw-Rzkvm4TNRvV180YQ/s1600/image.png";
const narratedVideo="https://m4lcas1da6glkve7.public.blob.vercel-storage.com/lv_0_20261020075359.mp4";
(function(){
"use strict";
const $=s=>document.querySelector(s);
const hold=$("#holdScreen"),app=$("#experience"),stage=$("#screenStage"),progress=$("#progressNav");
const videoId=1,totalSteps=chapters.length+2;
let step=-1,auto=false,sound=false,autoTimer=null,waterTimer=null,liveVideo=null,photoDialog=$("#imageDialog");
let audioContext=null,modalItems=[],modalIndex=0,originFocus=null;
const prefersReduced=()=>window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* Un único elemento de video conserva su buffer al cambiar de escena.
   Se crea sin autoplay. El navegador decide si acepta preload="auto". */
const mediaDepot=document.createElement("div");
mediaDepot.id="expoMediaDepot";
mediaDepot.hidden=true;
mediaDepot.setAttribute("aria-hidden","true");
document.body.appendChild(mediaDepot);
const preparedVideo=document.createElement("video");
preparedVideo.id="embeddedVideo";
preparedVideo.controls=true;
preparedVideo.playsInline=true;
preparedVideo.preload="metadata";
preparedVideo.setAttribute("aria-label","Video narrado de Pollazo Galapagueño");
preparedVideo.src=narratedVideo;
mediaDepot.appendChild(preparedVideo);

/* Precarga gradual de fotos: primero la apertura, luego las siguientes
   en segundo plano. Dos solicitudes simultáneas como máximo. */
const network=navigator.connection||navigator.mozConnection||navigator.webkitConnection;
const dataSaver=!!network?.saveData;
const slowNetwork=/^(slow-2g|2g)$/.test(network?.effectiveType||"");
const warmAssets=[...new Set(chapters.flatMap(ch=>ch.gallery?.length?ch.gallery.map(p=>p.src):[ch.src]).concat(brandLogo))];
const warmCache=new Map();
let warmCursor=0,warmActive=0;
function warmNextImage(){
 // Dar prioridad de red a la narración cuando ya se está reproduciendo.
 if(document.hidden||!preparedVideo.paused)return;
 const limit=(dataSaver||slowNetwork)?2:warmAssets.length;
 while(warmActive<2&&warmCursor<limit){
   const url=warmAssets[warmCursor++];
   if(warmCache.has(url))continue;
   const img=new Image();
   warmCache.set(url,img);
   img.decoding="async";
   img.referrerPolicy="no-referrer";
   warmActive++;
   img.onload=img.onerror=()=>{
     warmActive=Math.max(0,warmActive-1);
     window.setTimeout(warmNextImage,350);
   };
   img.src=url;
 }
}
function warmNextScene(){
 if(warmCursor<warmAssets.length&&!dataSaver&&!slowNetwork)warmNextImage();
}
function warmVideo(){
 if(dataSaver||slowNetwork)return;
 // Prepárate para reproducir, pero nunca llames play() aquí.
 preparedVideo.preload="auto";
 if(preparedVideo.readyState===0)preparedVideo.load();
}
window.addEventListener("load",()=>{
 const run=()=>{warmNextImage();warmVideo();};
 if("requestIdleCallback" in window)window.requestIdleCallback(run,{timeout:1800});
 else window.setTimeout(run,900);
},{once:true});
document.addEventListener("visibilitychange",()=>{if(!document.hidden)warmNextScene()});

/* Primer clic: pedir pantalla completa UNA sola vez. F11 utiliza el modo
   del navegador, distinto a la Fullscreen API. No invocamos exitFullscreen. */
document.addEventListener("click",()=>{
 warmVideo();
 if(document.fullscreenElement||!document.fullscreenEnabled)return;
 const available=window.screen?.availHeight||window.innerHeight;
 const alreadyBrowserFullscreen=window.innerHeight>=available-12;
 if(alreadyBrowserFullscreen)return;
 try{
   const promise=document.documentElement.requestFullscreen?.();
   promise?.catch?.(()=>{});
 }catch(_){}
},{once:true,capture:true});

function escapeText(value){return String(value||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function soundFx(type){
 if(!sound||prefersReduced())return;
 try{
 const CT=window.AudioContext||window.webkitAudioContext;if(!CT)return;
 audioContext=audioContext||new CT();
 if(audioContext.state==="suspended")audioContext.resume();
 const t=audioContext.currentTime,o=audioContext.createOscillator(),g=audioContext.createGain();
 o.type=type==="start"?"sine":"triangle";
 o.frequency.setValueAtTime(type==="start"?390:470,t);
 o.frequency.exponentialRampToValueAtTime(type==="start"?700:370,t+.19);
 g.gain.setValueAtTime(.0001,t);
 g.gain.exponentialRampToValueAtTime(.026,t+.03);
 g.gain.exponentialRampToValueAtTime(.0001,t+.25);
 o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.27);
 }catch(_){}
}
function clearTimers(){if(autoTimer){clearTimeout(autoTimer);autoTimer=null}if(waterTimer){clearInterval(waterTimer);waterTimer=null}}
function enterPresentation(autoRequested){
 auto=!!autoRequested;
 hold.hidden=true;app.hidden=false;
 document.body.style.background="#f8f4ee";
 step=0;
 render();
 window.scrollTo({top:0,behavior:"auto"});
 soundFx("start");
}
function standby(){
 clearTimers();if(liveVideo){liveVideo.pause();mediaDepot.appendChild(liveVideo);liveVideo=null}
 if(photoDialog.open)photoDialog.close();
 app.hidden=true;hold.hidden=false;step=-1;
 window.scrollTo({top:0,behavior:"auto"});
}
function scheduleAuto(){
 if(autoTimer){clearTimeout(autoTimer);autoTimer=null}
 if(!auto||photoDialog.open||step<0||step===videoId)return;
 const duration=step===0?7000:step===totalSteps-1?18000:13500;
 autoTimer=setTimeout(()=>advance(),duration);
}
function advance(){
 if(step<0){enterPresentation(false);return}
 if(step===totalSteps-1){
  if(auto){step=0;render()}else standby();
  return;
 }
 transitionTo(step+1,true);
}
function retreat(){if(step>0)transitionTo(step-1,true)}
function transitionTo(next,playVideo){
 if(photoDialog.open)photoDialog.close();
 clearTimers();
 if(liveVideo){liveVideo.pause();mediaDepot.appendChild(liveVideo);liveVideo=null}
 step=Math.max(0,Math.min(totalSteps-1,next));
 render();
 soundFx(step===videoId?"start":"move");
 if(step===videoId&&playVideo)attemptVideo();
}
function attemptVideo(){
 if(!liveVideo)return;
 const player=liveVideo;
 const promise=player.play();
 if(promise&&promise.catch)promise.catch(async()=>{
   if(auto){
    try{
     player.muted=true;
     await player.play();
     if(player===liveVideo){
      $("#videoHint").textContent="Modo automático: video silenciado por el navegador. Puedes activar la narración.";
      $("#unmuteVideo").hidden=false;
     }
     return;
    }catch(_){}
   }
   if(player===liveVideo)$("#videoHint").textContent="Presiona ▶ en el video para reproducirlo.";
 });
}
function progressBar(){
 const names=["Apertura","Video narrado"].concat(chapters.map(c=>c.eyebrow));
 progress.innerHTML=names.map((name,i)=>'<button type="button" data-step="'+i+'" class="'+(i===step?"active":i<step?"past":"")+'" title="'+escapeText(name)+'" aria-label="Ir a '+escapeText(name)+'" aria-current="'+(i===step?"step":"false")+'"></button>').join("");
 const title=names[step]||"Presentación";
 $("#sceneLabel").textContent=title.toUpperCase();
 $("#sceneNumber").textContent=String(step+1).padStart(2,"0")+" / "+String(totalSteps).padStart(2,"0");
 $("#previousScene").disabled=step===0;
 const next=$("#nextScene");
 next.innerHTML=(step===0?'Ver video <span aria-hidden="true">▶</span>':step===videoId?'Continuar <span aria-hidden="true">→</span>':step===totalSteps-1?'Finalizar <span aria-hidden="true">↺</span>':'Siguiente <span aria-hidden="true">→</span>');
}
function opening(){
 const src=chapters[0].src;
 return '<section class="scene sceneOpening" aria-label="Apertura"><div class="sceneBg"><img src="'+src+'" alt="" fetchpriority="high" decoding="async"></div><span class="sceneStamp">PRESENTACIÓN DE MARCA · 2026</span><div class="openingCopy"><div class="smallTag">BIENVENIDOS · SANTA CRUZ, GALÁPAGOS</div><h2>Una historia de <em>cuidado, trabajo y confianza.</em></h2><p>Te invitamos a descubrir cómo comienza el recorrido del Pollazo Galapagueño y cómo sus productos llegan hasta los puntos de venta de Santa Cruz.</p></div></section>';
}
function videoScreen(){
 return '<section class="scene videoScene" aria-label="Video narrado"><div class="videoSceneTop"><div><span>CAPÍTULO ESPECIAL / EL RECORRIDO</span><h2>Conoce nuestra historia en imágenes.</h2></div><small>VIDEO NARRADO · 1 MIN 38 S</small></div><div class="filmFrame" id="filmFrame"><button id="unmuteVideo" type="button" class="videoUnmute" hidden>🔊 Activar narración</button><div id="videoError" class="videoIssue" hidden><strong>El video no se pudo reproducir.</strong><p>Puedes continuar con la presentación; las fotografías y el contenido siguen disponibles.</p><div class="videoErrorActions"><button id="retryVideo" type="button">Reintentar video ↻</button><button id="skipVideo" type="button">Continuar recorrido →</button></div></div></div><div class="videoSceneFoot"><span id="videoHint">Reproduce el video para comenzar el recorrido.</span><strong>DE LA GRANJA A CADA ENTREGA</strong></div></section>';
}
function galleryMarkup(chapter){
 const imgs=chapter.gallery&&chapter.gallery.length?chapter.gallery:[{src:chapter.src,alt:chapter.alt,label:chapter.caption}];
 return imgs.map((item,k)=>'<img class="chapterImage '+(k===0?"active":"inactive")+'" data-gallery-item="'+k+'" src="'+item.src+'" alt="'+escapeText(item.alt)+'" referrerpolicy="no-referrer" loading="eager">').join("");
}
function keywords(chapter){
 const map={
 "CRIANZA":["CUIDADO","CRECIMIENTO","BIENESTAR"],
 "PERSONAS":["EQUIPO","SUPERVISIÓN","DEDICACIÓN"],
 "PRODUCTO":["PREPARACIÓN","PRESENTACIÓN","IDENTIDAD"],
 "DISTRIBUCIÓN":["TRANSPORTE","PUNTOS DE VENTA","SANTA CRUZ"],
 "CIERRE":["GRACIAS","COMPROMISO","GALÁPAGOS"],
 "ORIGEN":["INSTALACIONES","NUESTRO PROCESO","SANTA CRUZ"]
 };
 return (map[chapter.section]||[]).slice(0,3).map(v=>'<span>'+v+'</span>').join("");
}
function chapterScreen(chapter,index){
 if(index===chapters.length-1)return finalScreen(chapter);
 const isWater=!!(chapter.gallery&&chapter.gallery.length>1);
 return '<section class="scene chapterScene '+(chapter.reversed?"reversed":"")+'" aria-label="'+escapeText(chapter.eyebrow)+'"><div class="chapterCopy"><div class="chapterPosition">ETAPA '+String(index+1).padStart(2,"0")+' <span>'+escapeText(chapter.section)+'</span></div><h2>'+escapeText(chapter.title)+'</h2><p>'+escapeText(chapter.body)+'</p><div class="chapterKeywords">'+keywords(chapter)+'</div><p class="chapterDetail" id="chapterDetail">'+escapeText(chapter.note)+'</p></div><div class="chapterVisual" style="--photo:url(&quot;'+chapter.src+'&quot;)"><div class="chapterVisualTop">'+escapeText(chapter.eyebrow.toUpperCase())+'</div>'+galleryMarkup(chapter)+(isWater?'<div class="waterControls"><button data-water="0" class="active" type="button">Bebederos</button><button data-water="1" type="button">Filtros de agua</button></div>':'')+'<div class="chapterVisualBottom"><span>'+escapeText(chapter.caption)+'</span><button class="zoomBtn" type="button" id="openImage">Ampliar imagen ↗</button></div><div class="loadingNotice" id="imageProblem" hidden>La fotografía está temporalmente no disponible.</div></div></section>';
}
function finalScreen(chapter){
 return '<section class="scene finalScene" aria-label="Cierre de marca"><div class="finalCopy"><span class="smallTag">GRACIAS POR ACOMPAÑARNOS</span><h2>Del cuidado en cada etapa, <em>a la confianza en cada entrega.</em></h2><p>Gracias por conocer el trabajo que hay detrás del Pollazo Galapagueño. ¿Tienen alguna pregunta? Será un gusto conversar.</p><div class="finalBrand"><img src="'+brandLogo+'" alt="Pollazo Galapagueño"></div><span class="finalThankyou">EL NÚMERO UNO EN EL MERCADO</span></div><div class="finalVisual"><img src="'+chapter.src+'" alt="'+escapeText(chapter.alt)+'"></div></section>';
}
function render(){
 const chapterIndex=step-2;
 warmNextScene();
 if(step===0)stage.innerHTML=opening();
 else if(step===videoId)stage.innerHTML=videoScreen();
 else stage.innerHTML=chapterScreen(chapters[chapterIndex],chapterIndex);
 progressBar();
 if(step===videoId){
  // Reutilizamos exactamente el mismo elemento y su descarga ya iniciada.
  $("#filmFrame").prepend(preparedVideo);
  liveVideo=preparedVideo;
  liveVideo.preload="auto";
  liveVideo.onended=()=>{
   if(step!==videoId)return;
   $("#videoHint").textContent="Video finalizado. Continuamos con el recorrido…";
   autoTimer=setTimeout(()=>transitionTo(2,false),1600);
  };
  liveVideo.onerror=()=>{
   if(step!==videoId)return;
   $("#videoError").hidden=false;
   $("#videoHint").textContent="El video necesita reconexión.";
  };
  liveVideo.onplaying=()=>{
   if(step!==videoId)return;
   $("#videoError").hidden=true;
   $("#videoHint").textContent="Reproduciendo el recorrido audiovisual…";
  };
  liveVideo.onwaiting=()=>{
   if(step===videoId)$("#videoHint").textContent="Cargando un poco más de video…";
  };
  liveVideo.onstalled=()=>{
   if(step===videoId)$("#videoHint").textContent="Conexión lenta: esperando video…";
  };
  liveVideo.onpause=()=>{
   warmNextImage();
   if(step===videoId&&!liveVideo.ended)$("#videoHint").textContent="Video en pausa. Presiona ▶ para continuar.";
  };
  $("#retryVideo").addEventListener("click",()=>{
   if(step!==videoId)return;
   $("#videoError").hidden=true;
   $("#videoHint").textContent="Reintentando cargar el video…";
   preparedVideo.load();
   attemptVideo();
  });
  $("#skipVideo").addEventListener("click",()=>transitionTo(2,false));
  $("#unmuteVideo").addEventListener("click",()=>{
   if(!liveVideo)return;
   liveVideo.muted=false;
   $("#unmuteVideo").hidden=true;
   $("#videoHint").textContent="Narración activada.";
   liveVideo.play().catch(()=>{$("#videoHint").textContent="Utiliza los controles del video para reproducir el audio."});
  });
 }
 else if(chapterIndex>=0&&chapterIndex<chapters.length-1){
  const chapter=chapters[chapterIndex],gallery=chapter.gallery&&chapter.gallery.length>1?chapter.gallery:[{src:chapter.src,alt:chapter.alt,label:chapter.caption}];
  let visibleIndex=0;
  const imgs=stage.querySelectorAll("[data-gallery-item]");
  imgs.forEach((img,index)=>{
   img.addEventListener("error",()=>{if(index===0){$("#imageProblem").hidden=false}else img.hidden=true});
  });
  const setGallery=(newIndex)=>{
   if(!gallery.length)return;
   if(imgs[newIndex]?.hidden)return;
   visibleIndex=newIndex;
   imgs.forEach((img,i)=>{img.classList.toggle("active",i===newIndex);img.classList.toggle("inactive",i!==newIndex)});
   stage.querySelectorAll("[data-water]").forEach(btn=>btn.classList.toggle("active",Number(btn.dataset.water)===newIndex));
   const visual=stage.querySelector(".chapterVisual");visual.style.setProperty("--photo",'url("'+gallery[newIndex].src+'")');
  };
  if(gallery.length>1){
   const waterButtons=stage.querySelectorAll("[data-water]");
   waterButtons.forEach(button=>button.addEventListener("click",()=>{setGallery(Number(button.dataset.water));if(waterTimer)clearInterval(waterTimer);waterTimer=setInterval(()=>setGallery((visibleIndex+1)%gallery.length),4500)}));
   if(!prefersReduced())waterTimer=setInterval(()=>{if(!photoDialog.open)setGallery((visibleIndex+1)%gallery.length)},4500);
  }
  $("#openImage").addEventListener("click",()=>showDialog(chapter,visibleIndex));
 }
 scheduleAuto();
}
function showDialog(chapter,index){
 modalItems=chapter.gallery?.length?chapter.gallery:[{src:chapter.src,alt:chapter.alt,label:chapter.caption}];
 modalIndex=index||0;originFocus=document.activeElement;
 $("#imageDialogTitle").textContent=chapter.eyebrow;
 photoDialog.showModal();
 document.body.style.overflow="hidden";
 fillDialog();
}
function fillDialog(){
 const item=modalItems[modalIndex],img=$("#dialogImage");
 img.alt=item.alt||"Fotografía del recorrido";
 img.hidden=false;$("#dialogError").hidden=true;
 img.src=item.src;$("#dialogDescription").textContent=item.label||"FOTOGRAFÍA DEL RECORRIDO";
 $("#dialogCount").textContent=String(modalIndex+1).padStart(2,"0")+" / "+String(modalItems.length).padStart(2,"0");
 $("#dialogPrev").hidden=modalItems.length<2;$("#dialogNext").hidden=modalItems.length<2;
}
function moveDialog(delta){if(modalItems.length<2)return;modalIndex=(modalIndex+delta+modalItems.length)%modalItems.length;fillDialog()}
$("#startGuided").addEventListener("click",()=>enterPresentation(false));
$("#startAuto").addEventListener("click",()=>enterPresentation(true));
$("#backToHold").addEventListener("click",e=>{
 const btn=e.currentTarget;btn.classList.remove("logoBounce");void btn.offsetWidth;btn.classList.add("logoBounce");
 setTimeout(()=>standby(),450);
});
$("#holdButton").addEventListener("click",standby);
$("#previousScene").addEventListener("click",retreat);
$("#nextScene").addEventListener("click",advance);
progress.addEventListener("click",e=>{
 const button=e.target.closest("[data-step]");if(button)transitionTo(Number(button.dataset.step),false);
});
$("#closeDialog").addEventListener("click",()=>photoDialog.close());
$("#dialogPrev").addEventListener("click",()=>moveDialog(-1));
$("#dialogNext").addEventListener("click",()=>moveDialog(1));
$("#dialogImage").addEventListener("error",()=>{$("#dialogImage").hidden=true;$("#dialogError").hidden=false});
photoDialog.addEventListener("close",()=>{document.body.style.overflow="";if(originFocus?.isConnected)originFocus.focus({preventScroll:true});modalItems=[]});
photoDialog.addEventListener("click",e=>{if(e.target===photoDialog)photoDialog.close()});
document.addEventListener("keydown",e=>{
 if(e.target?.closest("button")&&e.key==="Enter")return;
 if(photoDialog.open){
  if(e.key==="ArrowRight"){e.preventDefault();moveDialog(1)}
  if(e.key==="ArrowLeft"){e.preventDefault();moveDialog(-1)}
  return;
 }
 if(e.key==="Enter"&&step===-1){e.preventDefault();enterPresentation(false);return}
 if(step<0||["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName))return;
 if(["ArrowRight","PageDown"].includes(e.key)){e.preventDefault();advance()}
 else if(["ArrowLeft","PageUp"].includes(e.key)){e.preventDefault();retreat()}
 else if((e.key===" "||e.key==="Enter")&&step!==videoId){e.preventDefault();advance()}
});
})();